var APP_VERSION = '5.1.3';
function formatPersianAppVersion(version2 = APP_VERSION) {
  const digits2 = "\u06F0\u06F1\u06F2\u06F3\u06F4\u06F5\u06F6\u06F7\u06F8\u06F9";
  return String(version2).replace(/\d/g, (digit) => digits2[Number(digit)]);
}

