// app/utils/codeGenerator.js
function generateNextSequentialCode(prefix, existingList = [], codeFieldName = "code", defaultStartNumber = 1001) {
  if (!existingList || existingList.length === 0) {
    return `${prefix}${defaultStartNumber}`;
  }
  let maxNum = 0;
  const cleanPrefix = prefix.toUpperCase();
  for (const item of existingList) {
    if (!item)
      continue;
    const rawCode = String(item[codeFieldName] || item.fileNumber || item.nationalCode || "").trim();
    if (!rawCode)
      continue;
    const match = rawCode.match(/\d+/g);
    if (match) {
      const lastDigits = parseInt(match[match.length - 1], 10);
      if (!isNaN(lastDigits) && lastDigits > maxNum) {
        maxNum = lastDigits;
      }
    }
  }
  const nextNum = maxNum > 0 ? maxNum + 1 : defaultStartNumber;
  return `${prefix}${nextNum}`;
}
function validateAndConfirmManualCodeChange(autoCode, userCode, entityLabel = "\u0634\u0646\u0627\u0633\u0647") {
  const autoClean = autoCode.trim();
  const userClean = userCode.trim();
  if (!userClean) {
    alert(`\u0644\u0637\u0641\u0627\u064B ${entityLabel} \u0631\u0627 \u0648\u0627\u0631\u062F \u0646\u0645\u0627\u06CC\u06CC\u062F.`);
    return false;
  }
  if (autoClean && autoClean !== userClean) {
    const isConfirmed = window.confirm(`\u26A0\uFE0F \u0647\u0634\u062F\u0627\u0631 \u062A\u063A\u06CC\u06CC\u0631 \u062F\u0633\u062A\u06CC \u06A9\u062F \u0634\u0646\u0627\u0633\u0647:

\u06A9\u062F \u062A\u0648\u0644\u06CC\u062F\u0634\u062F\u0647 \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u062E\u0648\u062F\u06A9\u0627\u0631 \u062A\u0648\u0633\u0637 \u0633\u06CC\u0633\u062A\u0645 \xAB${autoClean}\xBB \u0628\u0648\u062F\u0647 \u0627\u0633\u062A\u060C \u0627\u0645\u0627 \u0634\u0645\u0627 \u0622\u0646 \u0631\u0627 \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u062F\u0633\u062A\u06CC \u0628\u0647 \xAB${userClean}\xBB \u062A\u063A\u06CC\u06CC\u0631 \u062F\u0627\u062F\u0647\u200C\u0627\u06CC\u062F.

\u0622\u06CC\u0627 \u0627\u0632 \u062B\u0628\u062A \u0627\u06CC\u0646 \u06A9\u062F \u062F\u0633\u062A\u06CC \u0627\u062E\u062A\u0635\u0627\u0635\u06CC \u0628\u0631\u0627\u06CC ${entityLabel} \u0627\u0637\u0645\u06CC\u0646\u0627\u0646 \u062F\u0627\u0631\u06CC\u062F\u061F`);
    return isConfirmed;
  }
  return true;
}

