    const description = cleanExcelStringValue(row["\u062A\u0648\u0636\u06CC\u062D\u0627\u062A"] || row["description"] || "", false);
    const active = cleanExcelBooleanValue(row["\u0648\u0636\u0639\u06CC\u062A"] || row["active"], true);
