// app/utils/pcpos.js
async function testSamanKishPosConnection(posIp = "", posPort = "8080") {
  const cleanIp = posIp ? posIp.split(".").map((part) => parseInt(part, 10).toString()).join(".") : "";
  try {
    const res = await fetch("/api/pcpos/saman/status", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ posIp: cleanIp, posPort })
    });
    if (!res.ok)
      throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    return {
      success: false,
      connected: false,
      latencyMs: 0,
      message: "\u062E\u0637\u0627 \u062F\u0631 \u0634\u0628\u06A9\u0647 \u06CC\u0627 \u0639\u062F\u0645 \u067E\u0627\u0633\u062E\u06AF\u0648\u06CC\u06CC \u0633\u0631\u0648\u0631 \u0627\u0635\u0644\u06CC \u062F\u0631 \u0628\u0631\u0631\u0633\u06CC \u0648\u0636\u0639\u06CC\u062A \u067E\u0648\u0632: " + err.message
    };
  }
}

// app/components/SettingsBackup.js
var FiscalYearManager = ({ settings, onSaveSettings, compact = false }) => {
  const current = String(settings?.currentFiscalYear || "1405");
  const initialYears = Array.isArray(settings?.fiscalYears) && settings.fiscalYears.length ? settings.fiscalYears : [{ id: "fy-1405", year: current, startDate: `${current}/01/01`, endDate: `${current}/12/29`, status: "open", closedAt: "", closedBy: "", openingBalances: { cash: 0, bank: 0, receivables: 0, payables: 0 } }];
  const [years, setYears] = useState(initialYears);
  const [selected, setSelected] = useState(current);
  const [newYear, setNewYear] = useState("");
  const [opening, setOpening] = useState({ cash: 0, bank: 0, receivables: 0, payables: 0 });
  const [open, setOpen] = useState(false);
  useEffect(() => { setYears(initialYears); setSelected(current); }, [settings?.fiscalYears, settings?.currentFiscalYear]);
  const persist = (nextYears, nextCurrent = selected) => onSaveSettings?.({ ...settings, fiscalYears: nextYears, currentFiscalYear: String(nextCurrent) });
  const switchYear = () => {
    const target = years.find(y => String(y.year) === String(selected));
    if (!target || target.status === "closed") { alert("سال مالی بسته‌شده قابل انتخاب برای ثبت عملیات نیست."); return; }
    persist(years, selected); setOpen(false);
  };
  const createYear = () => {
    const y = String(newYear).replace(/\D/g, "");
    if (!/^1[34-9]\d{2}$/.test(y)) { alert("سال مالی را به‌صورت چهاررقمی وارد کنید؛ مثال: ۱۴۰۶"); return; }
    if (years.some(x => String(x.year) === y)) { alert("این سال مالی قبلاً تعریف شده است."); return; }
    const obj = { id: `fy-${y}`, year: y, startDate: `${y}/01/01`, endDate: `${y}/12/29`, status: "open", closedAt: "", closedBy: "", openingBalances: { ...opening } };
    const next = [...years, obj].sort((a,b) => String(a.year).localeCompare(String(b.year), "fa"));
    setYears(next); setSelected(y); setNewYear(""); setOpening({ cash:0, bank:0, receivables:0, payables:0 }); persist(next, y);
  };
  const closeYear = (y) => {
    if (String(y.year) !== current) { alert("فقط سال مالی جاری را می‌توان بست."); return; }
    if (!confirm(`سال مالی ${y.year} بسته شود؟ پس از بستن، ثبت عملیات مالی در این سال متوقف خواهد شد.`)) return;
    const next = years.map(x => String(x.year) === String(y.year) ? { ...x, status:"closed", closedAt:new Date().toISOString(), closedBy:"کاربر جاری" } : x);
    setYears(next); persist(next, current);
    alert(`سال مالی ${y.year} با موفقیت بسته شد. برای ادامه، یک سال مالی جدید باز کنید.`);
  };
  const reopenYear = (y) => {
    if (!confirm(`سال مالی ${y.year} مجدداً باز شود؟`)) return;
    const next = years.map(x => String(x.year) === String(y.year) ? { ...x, status:"open", closedAt:"", closedBy:"" } : x);
    setYears(next); persist(next, y.year);
  };
  return jsxs(Fragment, { children: [
    jsxs("div", { className: compact ? "bhis-fy-top" : "bhis-fy-manager", children: [
      jsxs("div", { className:"bhis-fy-current", children:[jsx("span",{className:"bhis-fy-label",children:"سال مالی"}), jsx("strong",{children:toPersianDigits(current)}), jsx("span",{className:"bhis-fy-status",children:(years.find(y=>String(y.year)===current)?.status==="closed"?"بسته":"باز")})]}),
      jsx("button", { type:"button", className:"bhis-fy-switch", onClick:()=>setOpen(true), children:"تغییر / مدیریت سال مالی" })
    ]}),
    open && jsxs("div", { className:"fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[120] flex items-center justify-center p-4", children:[
      jsxs("div", { className:"bhis-fy-modal", children:[
        jsxs("div",{className:"bhis-fy-modal-head",children:[jsxs("div",{children:[jsx("h2",{children:"مدیریت سال مالی"}),jsx("p",{children:"بستن دوره، بازکردن دوره جدید و انتقال مانده‌های افتتاحیه"})]}),jsx("button",{type:"button",className:"bhis-fy-close",onClick:()=>setOpen(false),children:"×"})]}),
        jsxs("div",{className:"bhis-fy-grid",children:[
          jsxs("section",{className:"bhis-fy-card",children:[jsx("h3",{children:"سال فعال"}),jsx("p",{children:"سال انتخاب‌شده مبنای ثبت عملیات مالی جدید و گزارش‌های مالی است."}),jsx("select",{value:selected,onChange:e=>setSelected(e.target.value),className:"w-full",children:years.map(y=>jsx("option",{value:y.year,disabled:y.status==="closed",children:`${toPersianDigits(y.year)} — ${y.status==="closed"?"بسته":"باز"}`},y.id))}),jsx("button",{type:"button",className:"bhis-fy-primary",onClick:switchYear,children:"ذخیره و فعال‌سازی سال انتخاب‌شده"})]}),
          jsxs("section",{className:"bhis-fy-card",children:[jsx("h3",{children:"باز کردن سال مالی جدید"}),jsx("p",{children:"سال جدید را تعریف کنید و مانده‌های افتتاحیه را ثبت نمایید."}),jsx("input",{value:newYear,onChange:e=>setNewYear(e.target.value),placeholder:"مثال: ۱۴۰۶",inputMode:"numeric",className:"w-full"}),jsxs("div",{className:"grid grid-cols-2 gap-2 mt-2",children:[jsx("input",{type:"number",value:opening.cash,onChange:e=>setOpening({...opening,cash:Number(e.target.value)}),placeholder:"موجودی صندوق"}),jsx("input",{type:"number",value:opening.bank,onChange:e=>setOpening({...opening,bank:Number(e.target.value)}),placeholder:"موجودی بانک"}),jsx("input",{type:"number",value:opening.receivables,onChange:e=>setOpening({...opening,receivables:Number(e.target.value)}),placeholder:"حساب‌های دریافتنی"}),jsx("input",{type:"number",value:opening.payables,onChange:e=>setOpening({...opening,payables:Number(e.target.value)}),placeholder:"حساب‌های پرداختنی"})]}),jsx("button",{type:"button",className:"bhis-fy-secondary",onClick:createYear,children:"ایجاد و فعال‌سازی سال جدید"})]}),
          jsxs("section",{className:"bhis-fy-card bhis-fy-wide",children:[jsx("h3",{children:"دوره‌های مالی"}),jsx("div",{className:"bhis-fy-table",children:years.map(y=>jsxs("div",{className:"bhis-fy-row",children:[jsxs("div",{children:[jsx("strong",{children:toPersianDigits(y.year)}),jsx("small",{children:`${toPersianDigits(y.startDate)} تا ${toPersianDigits(y.endDate)}`})]}),jsx("span",{className:y.status==="closed"?"fy-closed":"fy-open",children:y.status==="closed"?"بسته":"باز"}),jsx("span",{children:y.year===current?"سال جاری":""}),jsx("button",{type:"button",className:"bhis-fy-action",onClick:()=>y.status==="closed"?reopenYear(y):closeYear(y),children:y.status==="closed"?"بازگشایی":"بستن سال"})]},y.id))})]})
        ]}),
        jsx("div",{className:"bhis-fy-note",children:"کنترل سال مالی به‌صورت مرکز-محور ذخیره می‌شود و در نسخه پشتیبان نیز نگهداری خواهد شد. اسناد هر سال با برچسب سال مالی ذخیره می‌شوند و سال بسته‌شده برای ثبت عملیات جدید قفل است."})
      ]})
    ]})
  ]});
};

